import React, { useState, useEffect, useContext } from 'react';
import { Context } from "../index";
import { observer } from "mobx-react-lite";
import { Container, Table, Button, Modal, Form, Alert } from 'react-bootstrap';

const UsersList = observer(() => {
    const { user } = useContext(Context);
    const [users, setUsers] = useState([]);
    const [selectedUser, setSelectedUser] = useState(null);
    const [showEditModal, setShowEditModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [editForm, setEditForm] = useState({
        username: '',
        email: '',
        phone: ''
    });
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = async () => {
        setLoading(true);
        try {
            // Здесь будет запрос к API для получения всех пользователей
            // Пока используем mock данные для примера
            const mockUsers = [
                {
                    id: 1,
                    username: 'user1',
                    email: 'user1@example.com',
                    phone: '+79991234567',
                    role: 'USER',
                    createdAt: '2024-01-15'
                },
                {
                    id: 2,
                    username: 'admin',
                    email: 'admin@example.com',
                    phone: '+79997654321',
                    role: 'ADMIN',
                    createdAt: '2024-01-10'
                }
            ];
            setUsers(mockUsers);
            setError('');
        } catch (e) {
            setError('Ошибка при загрузке пользователей');
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    const handleEdit = (user) => {
        setSelectedUser(user);
        setEditForm({
            username: user.username || '',
            email: user.email || '',
            phone: user.phone || ''
        });
        setShowEditModal(true);
    };

    const handleUpdate = async () => {
        try {
            // Здесь будет запрос к API для обновления пользователя
            console.log('Updating user:', selectedUser.id, editForm);
            setShowEditModal(false);
            fetchUsers(); // Обновляем список
            setError('');
        } catch (e) {
            setError('Ошибка при обновлении пользователя');
        }
    };

    const handleDelete = async () => {
        try {
            // Здесь будет запрос к API для удаления пользователя
            console.log('Deleting user:', selectedUser.id);
            setShowDeleteModal(false);
            fetchUsers(); // Обновляем список
            setError('');
        } catch (e) {
            setError('Ошибка при удалении пользователя');
        }
    };

    const openDeleteModal = (user) => {
        setSelectedUser(user);
        setShowDeleteModal(true);
    };

    if (loading) {
        return (
            <Container className="mt-4">
                <div className="text-center">Загрузка...</div>
            </Container>
        );
    }

    return (
        <Container className="mt-4">
            <h2>Управление пользователями</h2>
            <p className="text-muted">Просмотр и управление всеми пользователями системы</p>
            
            {error && <Alert variant="danger">{error}</Alert>}

            <Table striped bordered hover responsive className="mt-3">
                <thead className="table-dark">
                    <tr>
                        <th>ID</th>
                        <th>Имя пользователя</th>
                        <th>Email</th>
                        <th>Телефон</th>
                        <th>Роль</th>
                        <th>Дата регистрации</th>
                        <th>Действия</th>
                    </tr>
                </thead>
                <tbody>
                    {users.map(userItem => (
                        <tr key={userItem.id}>
                            <td>{userItem.id}</td>
                            <td>{userItem.username}</td>
                            <td>{userItem.email}</td>
                            <td>{userItem.phone || 'Не указан'}</td>
                            <td>
                                <span className={`badge ${
                                    userItem.role === 'ADMIN' ? 'bg-danger' : 
                                    userItem.role === 'USER' ? 'bg-primary' : 'bg-secondary'
                                }`}>
                                    {userItem.role}
                                </span>
                            </td>
                            <td>{new Date(userItem.createdAt).toLocaleDateString('ru-RU')}</td>
                            <td>
                                <div className="d-flex gap-2">
                                    <Button 
                                        variant="outline-primary" 
                                        size="sm"
                                        onClick={() => handleEdit(userItem)}
                                    >
                                        ✏️
                                    </Button>
                                    <Button 
                                        variant="outline-danger" 
                                        size="sm"
                                        onClick={() => openDeleteModal(userItem)}
                                    >
                                        🗑️
                                    </Button>
                                </div>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </Table>

            {users.length === 0 && !loading && (
                <div className="text-center text-muted mt-4">
                    Пользователи не найдены
                </div>
            )}

            {/* Модальное окно редактирования */}
            <Modal show={showEditModal} onHide={() => setShowEditModal(false)}>
                <Modal.Header closeButton>
                    <Modal.Title>Редактирование пользователя</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <Form>
                        <Form.Group className="mb-3">
                            <Form.Label>Имя пользователя</Form.Label>
                            <Form.Control
                                type="text"
                                value={editForm.username}
                                onChange={(e) => setEditForm({...editForm, username: e.target.value})}
                            />
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Label>Email</Form.Label>
                            <Form.Control
                                type="email"
                                value={editForm.email}
                                onChange={(e) => setEditForm({...editForm, email: e.target.value})}
                            />
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Label>Телефон</Form.Label>
                            <Form.Control
                                type="text"
                                value={editForm.phone}
                                onChange={(e) => setEditForm({...editForm, phone: e.target.value})}
                                placeholder="Введите телефон"
                            />
                        </Form.Group>
                    </Form>
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={() => setShowEditModal(false)}>
                        Отмена
                    </Button>
                    <Button variant="primary" onClick={handleUpdate}>
                        Сохранить изменения
                    </Button>
                </Modal.Footer>
            </Modal>

            {/* Модальное окно удаления */}
            <Modal show={showDeleteModal} onHide={() => setShowDeleteModal(false)}>
                <Modal.Header closeButton>
                    <Modal.Title>Подтверждение удаления</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    Вы уверены, что хотите удалить пользователя <strong>{selectedUser?.username}</strong>?
                    <br />
                    <span className="text-danger">Это действие нельзя отменить.</span>
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={() => setShowDeleteModal(false)}>
                        Отмена
                    </Button>
                    <Button variant="danger" onClick={handleDelete}>
                        Удалить
                    </Button>
                </Modal.Footer>
            </Modal>
        </Container>
    );
});

export default UsersList;
